namespace {struct Result{std::vector<uint8_t>p;uint32_t w=0,h=0;uint64_t serial=0;};struct Settings{bool redEye=false,crop=false,level=true,flip=true;};class ImageAutoEnhanceTOP final:public TOP_CPlusPlusBase{
public:ImageAutoEnhanceTOP(const OP_NodeInfo*,TOP_Context*c):myContext(c){myThread=std::thread([this]{worker();});}~ImageAutoEnhanceTOP()override{{std::lock_guard<std::mutex>l(myMutex);myQuit=true;}myCond.notify_all();if(myThread.joinable())myThread.join();}void getGeneralInfo(TOP_GeneralInfo*g,const OP_Inputs*,void*)override{g->cookEveryFrameIfAsked=true;}
 void execute(TOP_Output*out,const OP_Inputs*in,void*)override{myExec++;bool active=in->getParInt("Active")!=0;Settings s;s.redEye=in->getParInt("Redeye");s.crop=in->getParInt("Crop");s.level=in->getParInt("Level");s.flip=in->getParInt("Flip");std::string sig=std::to_string(s.redEye)+std::to_string(s.crop)+std::to_string(s.level)+std::to_string(s.flip);if(sig!=mySig){mySig=sig;myLast=-1;}const OP_TOPInput*top=in->getInputTOP(0);if(active&&top&&(int64_t)top->totalCooks!=myLast){std::unique_lock<std::mutex>l(myMutex,std::try_to_lock);if(l.owns_lock()&&!myPending&&!myBusy){OP_TOPInputDownloadOptions o;o.pixelFormat=OP_PixelFormat::BGRA8Fixed;o.verticalFlip=s.flip;myDownload=top->downloadTexture(o,nullptr);if(myDownload){mySettings=s;myPending=true;myLast=top->totalCooks;mySubmit++;l.unlock();myCond.notify_one();}}}Result r;{std::lock_guard<std::mutex>l(myMutex);if(myResult.serial==myUploaded||myResult.p.empty())return;r=myResult;myUploaded=r.serial;}TOP_UploadInfo ui;ui.textureDesc.texDim=OP_TexDim::e2D;ui.textureDesc.width=r.w;ui.textureDesc.height=r.h;ui.textureDesc.pixelFormat=OP_PixelFormat::BGRA8Fixed;auto b=myContext->createOutputBuffer(r.p.size(),TOP_BufferFlags::None,nullptr);if(!b)return;memcpy(b->data,r.p.data(),r.p.size());out->uploadBuffer(&b,ui,nullptr);}
